export const DATA_92: ReadingTest[] = [
  { id: "rd-156", num: 156, title: "Đề 156", timeMin: 60, parts: [
    { title: "The Flame's Long Detour", paragraphs: ["Every four years, television audiences around the world watch a flame travel from Greece to the host city of the Olympic Games, carried by hand through dozens of countries before finally lighting the stadium cauldron. Many viewers assume this relay is an ancient tradition, passed down unchanged since the original Olympic Games in ancient Greece. The real history, however, is considerably shorter and stranger than most people realize. This gap between popular belief and documented history is not unusual, but the torch relay's case is unusually well documented, since photographs and film from its earliest years still survive.", "In ancient Greece, a fire did burn continuously at the temple of Hestia during the original Games, but there was no relay carrying it from city to city. The torch relay familiar today, in which runners pass a flame across long distances before the opening ceremony, was actually created for the first time in 1936, at the Berlin Olympics. Organizers of that particular Games designed the relay specifically to connect modern Germany, visually and symbolically, with the glory of ancient Greek civilization.", "This origin was, to put it plainly, deeply tied to propaganda. The 1936 Games were hosted by Nazi Germany, and the new torch relay served the regime's broader effort to present itself as the natural heir to a great, ancient European tradition. Film footage of the relay, carefully produced at the time, was used to reinforce this message far beyond the stadium itself, reaching audiences who never attended the Games in person.", "Despite this troubled beginning, the Olympic committee kept the torch relay after the Second World War ended, and it has appeared before every Games since. Over the following decades, its meaning shifted considerably away from its original purpose. Organizers began routing the flame through more countries, turning the relay into a shared moment of anticipation for people who would never see the Games in person, and the ceremony gradually became associated with global friendship rather than national pride of any single country. Some host countries even used the relay to showcase national landscapes or historic sites along the route, adding local meaning to a ceremony that had begun as something quite different.", "The torch relay today carries almost none of its original propaganda intent, at least in the minds of most people who watch it. This shift shows something important about how traditions work: a ritual invented for one clearly stated purpose can, given enough time and enough new hands carrying it, come to mean something almost entirely different from what its creators originally intended."], questions: [{ q: "According to the passage, what actually happened in ancient Greece regarding fire during the Olympic Games?", options: ["A fire burned continuously at the temple, with no relay between cities.", "A fire was relayed by runners between several ancient Greek cities.", "No fire of any kind was used during the ancient Olympic Games.", "A fire was lit only once, at the very end of the Games."], answer: 0 }, { q: "What is the passage mainly about?", options: ["The specific propaganda films produced during the 1936 Berlin Olympics.", "How the torch relay remains primarily a symbol of 1930s German propaganda today.", "Why every Olympic tradition was originally invented for political purposes.", "How the Olympic torch relay began as propaganda but later gained new meaning."], answer: 3 }, { q: "The word \"reinforce\" in paragraph 3 is closest in meaning to _______.", options: ["weaken", "strengthen", "hide", "invent"], answer: 1 }, { q: "According to the passage, how did the 1936 organizers use the torch relay?", options: ["To connect modern Germany symbolically with ancient Greek civilization.", "To raise money for the construction of the Olympic stadium.", "To train athletes for upcoming Olympic competition events.", "To celebrate friendship between Germany and Greece specifically."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as something the torch relay came to represent after World War II?", options: ["A shared moment of anticipation for people worldwide.", "A way to showcase a host country's landscapes or historic sites.", "A formal military alliance between participating host nations.", "A symbol of global friendship rather than national pride."], answer: 2 }, { q: "The word \"its\" in paragraph 4 refers to _______.", options: ["the Olympic committee", "the torch relay", "the Second World War", "the opening ceremony"], answer: 1 }, { q: "According to the passage, what did organizers do to expand the relay's reach after World War II?", options: ["They began routing the flame through more countries.", "They shortened the relay to fit within a single country only.", "They replaced the physical flame with a symbolic electronic light.", "They limited the relay strictly to professional athletes only."], answer: 0 }, { q: "What can be inferred about how traditions can change over time?", options: ["A ritual always retains exactly the meaning its original creators intended forever.", "Traditions only change meaning if a formal committee votes to redefine them.", "Most Olympic viewers today are fully aware of the relay's propaganda origins.", "A ritual can gradually come to mean something quite different from its creators' intent."], answer: 3 }, { q: "The word \"troubled\" in paragraph 4 is closest in meaning to _______.", options: ["peaceful", "difficult", "famous", "recent"], answer: 1 }, { q: "What is the author's overall attitude toward the torch relay's transformation over time?", options: ["Critical, arguing the relay should be discontinued because of its propaganda origins.", "Indifferent, treating the relay's history as unimportant to modern audiences.", "Approving, presenting the transformation as a positive example of changing meaning.", "Suspicious, implying the relay still secretly serves political propaganda today."], answer: 2 }] },
    { title: "The Hours Children Owe Their Brains", paragraphs: ["Recommendations on how much sleep children need have remained relatively stable for decades, yet the gap between those recommendations and how much sleep children actually get appears to be widening, driven by a combination of screen use before bedtime, increasing homework loads, and school schedules that conflict directly with how children's bodies are biologically inclined to rest.", "Sleep researchers have increasingly focused on what actually happens inside a child's brain during sleep, distinguishing it from adult sleep in several important respects. Deep, slow-wave sleep appears disproportionately important during childhood for consolidating memories formed during the day, effectively transferring information from short-term to more durable long-term storage. Sleep during these developmental years also coincides with substantial synaptic pruning, a process in which the brain selectively eliminates unused neural connections, refining circuits built up through the day's learning and experience.", "The consequences of chronically insufficient sleep in children are, unfortunately, rarely dramatic enough to draw immediate concern. Rather than obvious exhaustion, mild but persistent sleep restriction tends to manifest as subtler shifts — reduced attention span, greater emotional reactivity, diminished capacity for the kind of sustained, effortful thinking that schoolwork increasingly demands as children age. These symptoms are frequently misattributed to unrelated causes — a difficult personality, a learning difficulty, insufficient discipline — precisely because sleep deprivation rarely announces itself as the underlying explanation.", "School start times illustrate this tension particularly clearly, especially for adolescents. As children move through puberty, their internal circadian rhythm shifts measurably later, delaying the natural release of sleep-promoting hormones by an hour or more compared to younger children. Many secondary schools, however, continue to start considerably earlier than elementary schools, a scheduling pattern that runs directly counter to adolescents' biological sleep timing rather than accommodating it. Several districts that have experimentally delayed secondary school start times report measurable improvements in attendance, mood, and academic performance following the change.", "Despite this accumulating evidence, structural reform of school start times has proceeded slowly, complicated by competing logistical demands that have little to do with sleep science itself. Bus transportation schedules, coordinated across multiple school levels, are often difficult to rearrange without significant added cost. Parents' own work schedules frequently depend on predictable school start and pickup times, creating resistance to change that is not necessarily hostile to the underlying research but is nonetheless difficult to overcome through evidence alone.", "What emerges from this body of research is less a single decisive finding than an accumulating, largely invisible cost: sleep debt in children rarely registers as a distinct, easily attributed problem in daily life, yet it appears to shape attention, mood, and academic capacity in ways that conventional evaluations of a child's performance or behavior rarely account for directly. Addressing it convincingly would likely require treating sleep not as a private household matter but as a structural feature of how schools and communities are organized."], questions: [{ q: "According to the passage, what happens during synaptic pruning in a child's brain during sleep?", options: ["The brain selectively eliminates unused neural connections built during the day.", "The brain permanently stops forming any new neural connections at all.", "The brain transfers memories directly from long-term back into short-term storage.", "The brain strengthens every neural connection formed earlier that same day."], answer: 0 }, { q: "What is the passage mainly about?", options: ["The specific hormonal shift that delays adolescent sleep timing.", "How school transportation logistics are the central obstacle facing children's education.", "Why every child today suffers from severe, easily diagnosed sleep deprivation.", "How insufficient sleep quietly affects children's brains, behavior, and school performance."], answer: 3 }, { q: "The word \"consolidating\" in paragraph 2 is closest in meaning to _______.", options: ["erasing", "strengthening", "delaying", "interrupting"], answer: 1 }, { q: "How does insufficient sleep likely interfere with the memory-related brain processes described earlier?", options: ["By reducing attention and sustained thinking, it may undermine memory consolidation processes.", "By increasing the total amount of slow-wave sleep a child experiences overnight.", "By accelerating synaptic pruning far beyond what normal development requires.", "By replacing short-term memory storage entirely with long-term memory storage."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a subtle consequence of chronic mild sleep restriction in children?", options: ["A reduced attention span during schoolwork and daily tasks.", "Greater emotional reactivity in response to everyday situations.", "Noticeable, measurable weight loss over a period of months.", "Diminished capacity for sustained, effortful thinking during schoolwork."], answer: 2 }, { q: "The word \"it\" in paragraph 6 refers to _______.", options: ["school performance", "sleep debt", "academic capacity", "daily life"], answer: 1 }, { q: "According to the passage, what happens to adolescents' circadian rhythm during puberty?", options: ["It shifts measurably later, delaying sleep-promoting hormone release.", "It shifts measurably earlier, advancing sleep-promoting hormone release.", "It remains essentially unchanged throughout the adolescent years.", "It becomes completely unpredictable and impossible to measure reliably."], answer: 0 }, { q: "What can be inferred about why school start-time reform has proceeded slowly?", options: ["Most parents and school districts actively reject the underlying sleep research entirely.", "Bus transportation costs have already been fully eliminated as a barrier to reform.", "Sleep researchers have not yet studied the effects of delayed school start times.", "Logistical and scheduling constraints, not disagreement with the science, mainly explain the slow pace."], answer: 3 }, { q: "The word \"manifest\" in paragraph 3 is closest in meaning to _______.", options: ["disappear", "appear", "improve", "worsen"], answer: 1 }, { q: "What is the author's overall attitude toward how children's sleep needs are currently addressed?", options: ["Alarmed, warning that sleep deprivation is causing irreversible harm to most children today.", "Dismissive, suggesting concerns about children's sleep are largely exaggerated by researchers.", "Concerned but measured, arguing sleep debt's quiet costs deserve more structural attention.", "Optimistic, suggesting schools have already fully adapted to children's biological sleep needs."], answer: 2 }] },
    { title: "The Threshold That Keeps Moving", paragraphs: ["Ask most people what would make them lastingly happier, and the answer typically involves some concrete change: a higher salary, a nicer home, a long-awaited promotion. Decades of psychological research complicate this intuition considerably, suggesting that the satisfaction such achievements deliver tends to fade back toward a person's prior baseline far more quickly than most people anticipate when pursuing the change in the first place.", "This tendency, now widely studied under the label hedonic adaptation, was first brought to broad attention through a striking mid-1970s study comparing lottery winners to a control group and, separately, to individuals who had recently become paraplegic following an accident. Within roughly a year, both groups had drifted back toward remarkably similar levels of reported everyday happiness, a finding that struck many readers at the time as deeply counterintuitive, since the two life changes appeared, on the surface, to differ so drastically in magnitude and desirability.", "The mechanism proposed to explain this pattern centers on comparison rather than absolute circumstance. Rather than evaluating current conditions against some fixed, universal standard, people appear to judge their situation primarily against a reference point that continually recalibrates around whatever has recently become normal for them. A raise that once felt transformative becomes, within months, simply the new baseline income against which subsequent raises — or their absence — will be measured, a threshold that has, in effect, quietly relocated itself.", "This dynamic complicates the long-running debate over income and happiness considerably. Cross-sectional studies comparing wealthier and poorer individuals at a single point in time do find a positive association between income and reported wellbeing, though the relationship weakens noticeably above certain income thresholds in several major studies. Longitudinal studies tracking the same individuals over years, however, tell a somewhat different story: income gains that arrive gradually produce comparatively modest and often temporary boosts to reported happiness, since the reference point against which a person judges their financial situation tends to rise in step with the income itself.", "Adaptation is not confined to money. [1] Newly promoted employees typically report elevated job satisfaction in the months immediately following a promotion, a boost that recedes toward pre-promotion levels within roughly a year in several tracked cohorts. [2] Relationship satisfaction follows a broadly comparable arc for many couples, with an initial surge in reported happiness gradually settling toward a more stable baseline as novelty fades and daily routine reasserts itself. [3] Even material possessions once considered thrilling — a new car, a renovated kitchen — tend to become, with repeated exposure, simply part of an unremarkable daily backdrop rather than a continued source of active pleasure. [4]", "None of this evidence implies that circumstances are entirely irrelevant to wellbeing, nor that pursuing meaningful change is somehow misguided; severe hardship, unlike modest gains, appears considerably more resistant to full adaptation in several studies, and the speed of adaptation itself varies meaningfully across both individuals and specific life domains. What the research does suggest, more modestly, is that lasting satisfaction is unlikely to arrive through any single achievement treated as a final destination, and that practices emphasizing variety, deliberate savoring, and periodic novelty appear, in several intervention studies, to slow the pace of adaptation somewhat — though rarely, current evidence suggests, to halt it entirely."], questions: [{ q: "According to the passage, what did the mid-1970s study find about lottery winners and newly paraplegic individuals?", options: ["Within about a year, both groups reported similarly ordinary levels of everyday happiness.", "Lottery winners reported permanently higher happiness than the paraplegic group.", "Newly paraplegic individuals reported permanently higher happiness than lottery winners.", "Neither group showed any measurable change in happiness at any point studied."], answer: 0 }, { q: "What is the passage mainly about?", options: ["The specific 1970s study comparing lottery winners to accident survivors.", "How satisfaction from achievements tends to fade back toward a prior baseline.", "How severe hardship is now considered irrelevant to long-term wellbeing research.", "Why no achievement of any kind can ever produce any lasting happiness."], answer: 1 }, { q: "The word \"recalibrates\" in paragraph 3 is closest in meaning to _______.", options: ["resets", "disappears", "expands", "records"], answer: 0 }, { q: "Why do gradual income gains tend to produce only modest, temporary happiness boosts?", options: ["Because longitudinal studies fail to measure short-term happiness changes accurately.", "Because higher income directly causes measurable declines in relationship satisfaction.", "Because gradual income gains are usually smaller than sudden lump-sum gains.", "Because the reference point for judging income rises along with the income."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as an example of hedonic adaptation beyond money?", options: ["Job satisfaction fading back toward pre-promotion levels over time.", "Adaptation to chronic physical pain following a medical diagnosis.", "Relationship satisfaction settling toward a more stable baseline over time.", "Material possessions becoming an unremarkable part of daily life."], answer: 1 }, { q: "The word \"it\" in paragraph 6 refers to _______.", options: ["current evidence", "periodic novelty", "the pace of adaptation", "lasting satisfaction"], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'The same underlying pattern shows up reliably across several unrelated areas of life.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "What can be inferred about severe hardship's relationship to hedonic adaptation?", options: ["Severe hardship has been shown to produce little adaptation in most studies.", "Adaptation speed determined which individuals were selected for hardship-focused studies.", "Practices emphasizing variety and savoring appear to slow adaptation somewhat.", "Severe hardship appears to resist full adaptation more than modest gains do."], answer: 3 }, { q: "The word \"resistant\" in paragraph 6 is closest in meaning to _______.", options: ["resilient", "vulnerable", "similar", "temporary"], answer: 0 }, { q: "What is the author's overall attitude toward hedonic adaptation research and its practical implications?", options: ["Dismissive, arguing hedonic adaptation research has no practical relevance to daily life.", "Fully optimistic, claiming savoring practices completely eliminate hedonic adaptation.", "Measured, presenting adaptation as pervasive but only partially manageable through certain practices.", "Alarmed, warning that permanent happiness is now scientifically proven impossible."], answer: 2 }] },
    { title: "The Skill That Won't Travel Alone", paragraphs: ["Educators have long hoped that certain subjects — chess, Latin, formal logic, computer programming — might function as a kind of cognitive weightlifting, strengthening general reasoning ability that would then carry over into completely unrelated domains. This hope, appealing as it is, runs directly against a substantial body of research on what psychologists call transfer of learning, research that has repeatedly found such broad, effortless carryover to be considerably rarer than intuition suggests.", "Transfer researchers distinguish between two broad categories. Near transfer describes the application of a skill to a context closely resembling the one in which it was originally learned — solving a new algebra problem structurally similar to ones already practiced, for instance. Far transfer, by contrast, describes applying a skill or principle to a context that shares little surface similarity with the original learning environment, and it is precisely this far transfer that decades of research have found stubbornly difficult to produce reliably, even among learners who have achieved genuine mastery within the original domain.", "Chess offers a particularly well-studied example. Expert chess players demonstrably develop extraordinary pattern recognition and calculation ability within the specific domain of chess itself, yet controlled studies comparing chess-trained students to matched control groups have found only modest, inconsistent evidence that this ability meaningfully improves general reasoning, mathematics performance, or academic achievement more broadly. The discrepancy between chess's popular reputation as a mind-sharpening activity and its measured effect on unrelated cognitive tasks illustrates the broader transfer problem with unusual clarity.", "What appears to determine whether transfer occurs at all is not mastery of the original skill alone but the degree of explicit, deliberate bridging built into instruction itself. [1] Learners rarely notice, on their own, the deep structural parallel between a problem they have already solved and a superficially different one they now face. [2] Instruction that explicitly draws attention to the underlying principle connecting two different-looking problems produces measurably better transfer than instruction that simply hopes learners will discover the connection independently. [3] This finding carries a somewhat deflating implication for any subject marketed primarily on its supposed general cognitive benefits: without deliberate, structured bridging to other domains, the benefits of mastering that subject appear to remain confined largely within the subject itself. [4]", "Programming instruction offers a particularly relevant contemporary case, given how frequently coding education is promoted using precisely this cognitive-weightlifting rationale — the claim that learning to code teaches 'computational thinking' skills that transfer broadly to problem-solving in unrelated domains. Evidence on this specific claim remains genuinely mixed; some carefully designed studies report modest transfer gains under particular instructional conditions, while others find no measurable transfer at all, and the field has not yet converged on which instructional features reliably distinguish the studies reporting a positive effect from those that do not.", "None of this implies that subjects failing to produce far transfer are therefore not worth teaching; chess, Latin, and programming plainly carry value on their own terms, independent of any broader cognitive spillover. The more defensible conclusion is narrower and considerably less marketable: skill acquired in one domain rarely travels unaccompanied into another, and where transfer is genuinely desired as an educational goal, it appears to require deliberate instructional design aimed explicitly at building that bridge, rather than simply hoping mastery in one area will quietly generalize on its own."], questions: [{ q: "According to the passage, what distinguishes far transfer from near transfer?", options: ["Far transfer applies a skill to a context with little surface similarity.", "Far transfer applies a skill only within the exact same subject area.", "Near transfer applies a skill to a completely unrelated academic subject.", "Near transfer requires substantially more instructional time than far transfer does."], answer: 0 }, { q: "What is the passage mainly about?", options: ["The specific research findings on chess training and mathematics performance.", "How skills learned in one domain rarely transfer broadly without deliberate instructional bridging.", "How programming education has now been proven completely useless for problem-solving.", "Why no subject taught in school ever provides any lasting cognitive benefit."], answer: 1 }, { q: "The word \"discrepancy\" in paragraph 3 is closest in meaning to _______.", options: ["gap", "agreement", "prediction", "improvement"], answer: 0 }, { q: "Why might chess training fail to improve students' general reasoning despite producing genuine chess expertise?", options: ["Because chess is inherently too simple a game to develop any transferable skill.", "Because control groups in these studies were never taught chess at all.", "Because chess mastery actually reduces a student's general reasoning ability over time.", "Because instruction typically lacks the explicit bridging needed to connect skills across domains."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a subject studied for possible far transfer effects?", options: ["Chess, studied for its effect on general reasoning ability.", "Music theory, studied for its effect on mathematical reasoning ability.", "Computer programming, studied for its effect on problem-solving skills.", "Latin, mentioned as a subject valued for its supposed cognitive benefits."], answer: 1 }, { q: "The word \"it\" in paragraph 6 refers to _______.", options: ["chess mastery", "instructional design", "far transfer", "programming education"], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This is not simply a matter of learners lacking sufficient intelligence or effort.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 1 }, { q: "What can be inferred about the marketing claims surrounding coding education?", options: ["Coding education has been definitively proven to provide no benefit of any kind.", "Mixed research findings caused coding education to be marketed using transfer claims.", "Some carefully designed studies report modest transfer gains under particular conditions.", "Current evidence does not yet clearly support the broad transfer claims often marketed."], answer: 3 }, { q: "The word \"deflating\" in paragraph 4 is closest in meaning to _______.", options: ["discouraging", "encouraging", "surprising", "confusing"], answer: 0 }, { q: "What is the author's overall stance on subjects marketed as providing broad cognitive benefits, such as chess or coding?", options: ["Fully dismissive, arguing these subjects have no educational value whatsoever.", "Skeptical of broad transfer claims, while affirming these subjects' value on their own terms.", "Fully supportive, confirming that these subjects reliably improve general reasoning ability.", "Uncertain, offering no assessment of these subjects' value in any respect."], answer: 1 }] },
  ] },
  { id: "rd-174", num: 174, title: "Đề 174", timeMin: 60, parts: [
    { title: "Getting Back Into Shape After the Holidays", paragraphs: ["For many people, the weeks following a major holiday season bring a familiar realization: months of rich food, late nights, and irregular schedules have left them feeling less fit than they would like. Rather than turning to extreme diets or quick fixes, more and more people are choosing a slower, steadier approach that combines regular exercise with realistic daily habits. Gyms and fitness studios typically see a noticeable rise in new members during this period, though studies suggest that many of these new members stop attending within just a few months if their initial routine was too demanding to sustain .", "Two of the most commonly recommended activities for this kind of gradual recovery are gym-based strength training and yoga, and trainers often suggest combining the two rather than choosing only one. Strength training helps build muscle, which in turn increases the number of calories the body burns even while resting, while yoga improves flexibility, balance, and can also reduce the stress that sometimes leads people to overeat in the first place. A beginner program usually starts with only two or three short sessions per week, since attempting daily intense workouts right away is one of the most common reasons people quit exercising altogether within the first month.", "Diet also plays an important supporting role, though most fitness experts caution against making drastic changes all at once. Instead of cutting out entire food groups immediately, nutritionists generally recommend gradually reducing portion sizes and replacing some fried or sugary foods with simpler alternatives, allowing the body and mind time to adjust without triggering the kind of intense cravings that often lead to giving up. Drinking enough water throughout the day is also frequently mentioned, since mild dehydration can sometimes be mistaken for hunger, leading people to eat more than they actually need.", "Consistency, according to most trainers, matters far more than intensity, especially in the early weeks of any new routine. Someone who exercises moderately three times a week for several months will typically see better long-term results than someone who exercises intensely every day for two weeks and then stops entirely from exhaustion or injury. For this reason, many gyms and yoga studios now offer beginner-friendly class schedules specifically timed for the weeks after major holidays, when demand for gentler, lower-pressure options is highest.", "Ultimately, most fitness professionals agree that the goal should not simply be losing the weight gained over the holiday season, but building habits flexible enough to last well beyond it. Small, sustainable changes to both exercise and diet, repeated patiently over time, tend to produce results that last far longer than any short, intense program ever could."], questions: [{ q: "According to the passage, why do many new gym members stop attending?", options: ["Gym membership fees rose sharply after New Year.", "Their initial routine was too demanding to sustain.", "Yoga studios offered better schedules than the gym.", "Their trainer canceled sessions during the busy season."], answer: 1 }, { q: "The word \"sustain\" in paragraph 1 is closest in meaning to _______.", options: ["speed up", "hold back", "keep up", "warm up"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Drinking sufficient water each day is the most critical factor in losing holiday weight quickly.", "A gradual, consistent combination of exercise and diet changes tends to build habits that last.", "Yoga is generally more effective than gym training for people recovering from holiday weight gain.", "Most new gym members quit permanently after the first few weeks of their new routine."], answer: 1 }, { q: "The word \"this\" in paragraph 2 refers to _______.", options: ["daily intense workouts", "new member increase", "gym and yoga", "stress reduction methods"], answer: 0 }, { q: "According to the passage, what do nutritionists generally recommend regarding diet changes?", options: ["Avoid drinking water until clear hunger signals appear.", "Eliminate entire food groups immediately for the fastest results.", "Gradually reduce portions and replace some foods with simpler options.", "Repeat the exact pre-holiday diet without any changes."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a benefit of yoga?", options: ["improving balance", "building muscle mass", "reducing stress", "improving flexibility"], answer: 1 }, { q: "The word \"drastic\" in paragraph 3 is closest in meaning to _______.", options: ["healthy", "delayed", "gradual", "extreme"], answer: 3 }, { q: "According to the passage, what do most trainers say matters more than intensity?", options: ["Eating fewer calories than recommended.", "Following a strict daily class schedule.", "Staying consistent with a routine over time.", "Choosing a costly gym membership plan."], answer: 2 }, { q: "What can be inferred from the passage about why beginner programs start with fewer sessions per week?", options: ["Starting with intense daily workouts often leads to early exhaustion.", "Gyms are usually overwhelmed with new members during major holidays.", "Yoga instructors are rarely available for weekday afternoon classes.", "Fewer sessions burn more calories than daily exercise routines."], answer: 0 }, { q: "What is the author's overall purpose in writing this passage?", options: ["To argue that dietary changes are unnecessary for health.", "To promote a specific yoga studio's new class schedule.", "To explain a gradual approach to post-holiday fitness.", "To criticize gyms for encouraging unsustainable trends."], answer: 2 }] },
    { title: "Understanding Landslide and Flood Risk in Mountainous Regions", paragraphs: ["Communities located near steep, forested slopes face a combination of hazards that rarely occur in isolation, since heavy rainfall capable of triggering a landslide is very often the same rainfall responsible for downstream flooding. Researchers studying these events have increasingly moved away from treating landslides and floods as separate categories of natural disaster, arguing instead that the two are frequently linked through a single underlying cause: prolonged or unusually intense rainfall that saturates soil beyond its capacity to hold water, at which point gravity, rather than the rain itself, becomes the immediate trigger for slope failure.", "Soil saturation does not happen instantly, which is part of why early warning systems increasingly track cumulative rainfall over several days rather than the intensity of any single storm. A relatively modest rainstorm falling on already-saturated ground can trigger a landslide that a storm of similar or even greater intensity would not cause on dry soil, meaning that rainfall totals from the preceding week are sometimes a better predictor of landslide risk than the rainfall total of the triggering storm itself. This distinction , while seemingly technical, has practical consequences for how warnings are issued and how much lead time residents actually receive.", "Deforestation compounds this risk considerably, since tree roots play a significant structural role in binding soil particles together and slowing the rate at which water infiltrates the ground. Slopes that have been cleared for agriculture or development, research consistently shows, experience landslides at meaningfully higher rates than comparable slopes that retain their original vegetation cover, even when rainfall amounts are held constant across both types of terrain. This has led some regional governments to restrict construction on steep slopes altogether, though enforcement of such restrictions varies considerably and is sometimes undermined by short-term economic pressure to develop available land.", "Once a landslide reaches a river or stream — which happens more often than many residents assume, given how frequently slope failures occur near waterways in mountainous terrain — it can temporarily block the channel, creating what geologists call a landslide dam. These natural dams are frequently unstable, and when they eventually fail, the water and debris held behind them are released suddenly, sometimes producing floods considerably more destructive than would have occurred from rainfall alone, since the resulting surge combines fast-moving water with large volumes of accumulated sediment and debris.", "Community preparedness in landslide-prone regions has, in recent years, shifted correspondingly from a narrow focus on flood-specific measures — such as levees and drainage channels — toward more integrated approaches that account for both hazards simultaneously. Evacuation routes are now more frequently planned with slope stability in mind, not just flood elevation, since a route that avoids low-lying flood zones may nonetheless cross terrain vulnerable to a landslide triggered by the very same storm.", "Some rural communities, lacking the resources for sophisticated monitoring equipment, have instead adopted simpler observational practices, training residents to recognize early warning signs such as new cracks in the ground, tilting trees, or sudden changes in the clarity of stream water — indicators that, while less precise than instrumented monitoring, have in several documented cases provided enough advance notice for successful evacuation before a slope failure occurred."], questions: [{ q: "What is the main idea of the passage?", options: ["Landslides and floods often share a single cause of prolonged rainfall, so preparedness now covers both.", "Modern warning systems now predict landslides with almost complete accuracy in every region.", "Deforestation alone explains nearly every landslide and flood recorded in mountainous regions worldwide.", "Landslide dams are the leading cause of most major floods across mountainous terrain today."], answer: 0 }, { q: "According to the passage, why do early warning systems track rainfall over several days rather than a single storm's intensity?", options: ["Cumulative rainfall figures are simply easier for residents to understand than storm data.", "Single storms rarely produce enough rainfall to affect soil conditions at all.", "Soil saturation builds gradually, so a modest storm on wet ground can trigger a landslide.", "Single-storm intensity cannot be measured accurately with any current monitoring technology."], answer: 2 }, { q: "The phrase \"This distinction\" in paragraph 2 refers to _______.", options: ["rural versus urban evacuation planning", "preceding rainfall versus triggering-storm rainfall", "landslide dams versus river channels", "vegetated versus deforested slopes"], answer: 1 }, { q: "The word \"saturates\" in paragraph 1 is closest in meaning to _______.", options: ["dries out", "moistens lightly", "fills completely", "erodes slowly"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a way communities prepare for landslide risk?", options: ["planning slope-aware evacuation routes", "installing satellite soil sensors nationwide", "tracking cumulative rainfall totals", "training residents on warning signs"], answer: 1 }, { q: "Based on the passage, why do deforested slopes experience landslides at higher rates than vegetated slopes?", options: ["Tree roots bind soil and slow infiltration, a role lost when cleared.", "Deforested slopes always receive more total rainfall than forested slopes.", "Government restrictions apply only to slopes that remain forested.", "Deforested slopes sit at higher elevations than forested slopes generally."], answer: 0 }, { q: "What is the author's overall attitude toward the relationship between landslides and floods?", options: ["dismissive of community-level preparedness efforts as ineffective", "skeptical that any real link between the hazards exists", "alarmist, stressing worst outcomes without discussing preparedness", "objective, presenting the link as well-supported scientific understanding"], answer: 3 }, { q: "The word \"integrated\" in paragraph 5 is closest in meaning to _______.", options: ["combined", "outdated", "simplified", "separated"], answer: 0 }, { q: "According to the passage, what happens when a landslide dam eventually fails?", options: ["Surrounding vegetation regrows more quickly than on other slopes.", "Water and debris are released suddenly, sometimes causing severe flooding.", "Governments are required to rebuild the waterway immediately after.", "The river channel becomes permanently blocked from further flow."], answer: 1 }, { q: "What can be inferred from the passage about why evacuation routes now account for slope stability?", options: ["Flood elevation data is generally unreliable in most mountainous regions.", "Landslides only occur in areas that are also flood-prone.", "Slope stability is easier to measure than flood risk in general.", "A route avoiding flood zones may still cross terrain vulnerable to landslides."], answer: 3 }] },
    { title: "The Persistence of the Ten-Percent Brain Myth", paragraphs: ["Few claims about human biology have proven as durable , or as thoroughly contradicted by evidence, as the assertion that people use only ten percent of their brains. Despite decades of neuroscientific research demonstrating otherwise, the notion continues to circulate in popular culture, occasionally resurfacing in films, self-help literature, and casual conversation as though it were an established scientific fact rather than a persistent misconception whose origins remain, even now, somewhat murky to historians of science.", "Where exactly the myth originated is itself a matter of some dispute, though several plausible sources have been proposed over the years. Some historians trace it to a misreading of early twentieth-century neurological research, in which scientists — working with far more limited imaging technology than exists today — observed that only a fraction of neurons appeared active during any single simple task, a finding since shown to reflect the brain's efficient allocation of resources rather than any genuine underutilization of overall capacity. Others attribute the claim's popularization less to scientific misreading and more to self-help authors and motivational speakers, who found the notion of vast untapped mental potential rhetorically useful regardless of its accuracy.", "Modern neuroimaging has since made the myth considerably harder to sustain, whatever its origin. Techniques such as functional MRI, which track blood flow and metabolic activity across the brain in near real time, reveal that virtually all regions show measurable activity over the course of a normal day, even if not every region is maximally active during any single given moment. Furthermore, patients who have suffered damage to even seemingly small areas of brain tissue frequently experience significant and often permanent impairment, a pattern that would be difficult to explain if ninety percent of the brain were, as the myth implies, functionally expendable.", "Evolutionary considerations offer a further line of argument against the myth, one that some researchers find more persuasive than the neuroimaging evidence alone. The human brain, despite constituting only a small fraction of total body mass, consumes a disproportionately large share of the body's total energy budget — a metabolic cost that natural selection would be unlikely to have preserved across many generations had ninety percent of that costly tissue been providing no functional benefit whatsoever. This argument does not by itself prove that every neuron is essential at every moment, but it does suggest that large-scale, permanent underutilization would have carried an evolutionary cost difficult to justify.", "Why the myth persists despite this accumulated evidence is a separate question from whether it is true, and one that some cognitive scientists find nearly as interesting as the original claim itself. Part of the explanation may lie in the appeal of the idea itself: the notion that untapped potential lies dormant within nearly everyone offers a more hopeful, motivating narrative than the comparatively mundane reality that most people already use the great majority of their brain, most of the time, simply not all of it at once for any single task. Whether correcting the myth actually diminishes its motivational appeal, or whether the two can coexist without contradiction, remains an open question that popular science communicators continue to grapple with.", "What the myth ultimately illustrates, beyond its own specific inaccuracy, is a broader pattern in how scientific misconceptions take hold and endure: a claim need not be true, or even plausible under close scrutiny, to become deeply embedded in popular understanding, provided it offers a narrative more satisfying than the more complicated, less dramatic truth it displaces."], questions: [{ q: "According to the passage, what led to the initial emergence of the ten-percent myth?", options: ["A misunderstanding of early research on neuron activation levels.", "A deliberate attempt by self-help authors to deceive consumers.", "An inaccurate translation of twentieth-century medical journals.", "A flawed brain-imaging study that was later officially retracted."], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Scientific evidence disproves the myth, but its popularity endures.", "Modern neuroimaging was created specifically to counter brain myths.", "Evolutionary biology fails to account for human brain energy use.", "Motivational speakers invented the myth strictly for financial gain."], answer: 0 }, { q: "The word \"it\" in paragraph 1 refers to _______.", options: ["The ongoing debate among historians of cognitive science.", "The widespread assertion that humans use ten percent of brain power.", "The general field of modern neuroscientific research today.", "The general fascination with biology found in popular culture."], answer: 1 }, { q: "The word \"durable\" in paragraph 1 is closest in meaning to _______.", options: ["short-lived", "widely doubted", "long-lasting", "easily proven"], answer: 2 }, { q: "According to the passage, what does the brain's disproportionate energy consumption suggest about the myth?", options: ["The brain's energy use has no bearing on evolutionary reasoning at all.", "Energy consumption data cannot be measured accurately in modern neuroscience.", "Natural selection would unlikely preserve costly tissue providing no benefit.", "The brain actually consumes very little of the body's total energy."], answer: 2 }, { q: "According to the passage, which of the following is NOT presented as evidence against the ten-percent myth?", options: ["damage to small brain areas causing significant impairment", "fMRI showing activity across virtually all brain regions", "surveys showing most people already reject the myth", "the brain's disproportionately high energy consumption"], answer: 2 }, { q: "What can be inferred from the passage about why neuroimaging evidence alone has not fully eliminated the myth?", options: ["Evolutionary arguments have completely replaced neuroimaging as the accepted proof.", "The myth's appeal may rest more on its hopeful narrative than on evidence.", "Most people have never been exposed to any neuroimaging findings at all.", "Neuroimaging technology remains too imprecise for most researchers to trust."], answer: 1 }, { q: "According to the final paragraph, what does the ten-percent myth ultimately illustrate?", options: ["that a claim can endure in popular belief without needing to be true", "that self-help literature is generally more accurate than academic research", "that neuroscientists rarely agree on the origins of popular misconceptions", "that brain-imaging technology has resolved every major neuroscience debate"], answer: 0 }, { q: "The word \"dormant\" in paragraph 5 is closest in meaning to _______.", options: ["damaged", "expanding", "inactive", "exhausted"], answer: 2 }, { q: "What is the author's overall attitude toward the ten-percent brain myth?", options: ["Sympathetic, holding out hope that the claim may be validated.", "Indignant, condemning those who continue to spread the misconception.", "Analytical, examining its flaws alongside reasons for its persistence.", "Dismissive, refusing to discuss the myth's impact on popular culture."], answer: 2 }] },
    { title: "Rebuilding After the Storm: An Island Community's Long Recovery", paragraphs: ["Not only did the typhoon that struck the island destroy the majority of its fishing fleet, but it also, in ways that took considerably longer to become apparent, damaged the underlying economic and social structures that had sustained the community for generations — a slower, less visible form of harm that some disaster researchers argue ultimately proves more consequential than the storm's immediate physical destruction, even though media coverage typically fades long before this second, quieter phase of damage fully plays out.", "Initial recovery efforts, predictably enough, concentrated on the most visible needs: clearing debris, restoring electricity, and rebuilding damaged homes, tasks that international aid organizations are generally well equipped to address within the first several weeks following a disaster of this scale. What proved considerably harder to restore, however, was the informal economic network that had underpinned the island's fishing industry long before the storm — relationships between boat owners, processors, and buyers built up over years and, in some cases, decades, none of which could simply be rebuilt on the same timeline as a physical structure, however sophisticated the reconstruction effort.", "Government disaster relief funding, while substantial in absolute terms, was allocated according to a formula that some economists have since argued failed to account adequately for this distinction between physical and relational capital, since funding formulas of this kind are typically designed around measurable losses — destroyed boats, damaged buildings — rather than the far less quantifiable erosion of trust and established working relationships that disasters of this scale routinely cause but that rarely appear in any standard damage assessment. Whether revised formulas incorporating this relational dimension would meaningfully improve outcomes remains a matter some policy researchers continue to debate, absent clear evidence from comparable cases elsewhere.", "Migration patterns following the storm further complicated recovery, since a meaningful share of working-age residents, faced with an uncertain timeline for economic recovery, chose to relocate to the mainland in search of steadier employment rather than wait for the fishing industry to fully recover. This outmigration, while entirely rational from an individual household's perspective, arguably slowed the very recovery those departing residents might otherwise have contributed to, since a smaller working-age population left the aging fleet of remaining fishermen struggling to rebuild the informal networks that outmigration itself had further weakened — an unintended, self-reinforcing dynamic that few initial relief plans had anticipated.", "Some outside observers, drawing on the island's difficult experience, have proposed that future disaster relief frameworks ought to incorporate explicit provisions for relational and economic capital rather than focusing narrowly on physical reconstruction, arguing that failing to do so risks repeating the same slow, quiet erosion documented here in future disasters elsewhere. Whether such reforms will materialize, and whether they would meaningfully alter recovery outcomes even if adopted, remains genuinely uncertain, and reasonable disaster-policy analysts continue to disagree on both points.", "Years after the storm, the island's fishing industry has partially recovered, though most residents interviewed describe the community as functioning differently than it did before — smaller, somewhat less cohesive , and, according to several long-time fishermen, permanently altered in ways that no amount of reconstruction funding, however generously allocated, could have fully reversed."], questions: [{ q: "According to the passage, what form of harm does the author argue proved more consequential than the storm's immediate destruction?", options: ["the loss of the island's entire electrical grid infrastructure", "the slower damage to economic and social structures over time", "the temporary halt of international news coverage", "the destruction of homes located along the coastline"], answer: 1 }, { q: "What is the main idea of the passage?", options: ["Outmigration is the only meaningful factor determining an island community's long-term recovery.", "The storm's slower relational and economic damage proved harder to repair than physical destruction.", "International aid organizations failed entirely to address the island's most urgent physical needs.", "Government funding formulas are always the primary obstacle to effective disaster recovery."], answer: 1 }, { q: "The word \"this\" in paragraph 3 refers to _______.", options: ["the total amount of government relief funding allocated", "the number of boats destroyed during the typhoon", "the timeline international organizations used for debris removal", "the distinction between physical losses and relational capital erosion"], answer: 3 }, { q: "The word \"quantifiable\" in paragraph 3 is closest in meaning to _______.", options: ["deliberately hidden from view", "impossible to measure", "rapidly changing over time", "capable of being measured"], answer: 3 }, { q: "According to the passage, why did government relief funding fail to account for relational capital?", options: ["Funding formulas are typically designed around measurable, physical losses.", "The government intentionally excluded fishermen from relief funding entirely.", "Relational capital had already been fully restored before funding arrived.", "International aid organizations refused to share relevant damage data."], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as part of initial recovery efforts?", options: ["reforming national disaster funding formulas", "restoring electricity to the island", "rebuilding damaged residential homes", "clearing debris from damaged areas"], answer: 0 }, { q: "What can be inferred from the passage about the relationship between outmigration and the fishing industry's recovery?", options: ["Outmigration and weakened networks reinforced each other, slowing recovery further.", "Residents who left the island always returned once the fishing industry recovered.", "Outmigration had no measurable effect on the island's fishing industry at all.", "The fishing industry recovered fastest specifically because young workers had left."], answer: 0 }, { q: "According to the passage, what do some outside observers propose for future disaster relief frameworks?", options: ["relocating entire island populations before storms strike", "focusing exclusively on physical reconstruction going forward", "eliminating government funding formulas for fishing communities entirely", "incorporating explicit provisions for relational and economic capital"], answer: 3 }, { q: "The word \"cohesive\" in paragraph 6 is closest in meaning to _______.", options: ["expanding", "unified", "divided", "declining"], answer: 1 }, { q: "What is the author's overall stance toward whether future disaster relief reforms will be adopted?", options: ["dismissive, treating the entire reform debate as irrelevant to real outcomes", "genuinely uncertain, presenting the debate as unresolved among policy analysts", "strongly opposed to any changes in current relief funding formulas", "firmly confident that reforms will be adopted across all disaster-prone regions"], answer: 1 }] },
  ] },
];
